import React from 'react';
import ImageWithFallback from './ImageWithFallback';

const SkinDetailModal = ({ skin, onClose, onUpgrade }) => {
  if (!skin) return null;
  const rarity = skin.rarity || 'Mil-Spec';
  const rarityClass = `rarity-${rarity.toLowerCase().replace(/\s+/g, '-')}`;
  return <div className="skin-detail-overlay" role="dialog" aria-modal="true" onClick={onClose}>
    <div className="skin-detail-modal" onClick={(e)=>e.stopPropagation()}>
      <button className="skin-modal-close" onClick={onClose} aria-label="Fermer">×</button>
      <div className="skin-detail-art"><div className="skin-art-glow"/><ImageWithFallback src={skin.image_url} alt={skin.name} className="skin-detail-image"/><div className="skin-art-rarity">{rarity}</div></div>
      <div className="skin-detail-copy"><span className="section-kicker">WELLCASE / SKIN INSPECTOR</span><h2>{skin.name}</h2><div className={`skin-rarity-pill ${rarityClass}`}>{rarity}</div><div className="skin-stat-grid"><div><span>CATÉGORIE</span><strong>{skin.category || '—'}</strong></div><div><span>VALEUR</span><strong>{Number(skin.virtual_value||0).toLocaleString('fr-FR')} €</strong></div><div><span>FLOAT</span><strong>{skin.float_value != null ? Number(skin.float_value).toFixed(4) : 'N/A'}</strong></div><div><span>ÉTAT</span><strong>ACTIVE</strong></div></div><p className="skin-detail-note">Objet virtuel WellCase. Sa valeur peut être utilisée pour la vente ou comme base d'upgrade.</p><div className="skin-detail-actions"><button className="skin-secondary" onClick={onClose}>FERMER</button><button className="skin-primary" onClick={onUpgrade}>UPGRADE ↗</button></div></div>
    </div>
  </div>;
}; export default SkinDetailModal;
